/**
 * 输入法预览页面（无需激活输入法即可测试键盘）。
 *
 * 功能：
 * - 三语切换（柯语/英文/中文拼音）
 * - Shift / Shift Lock
 * - 拼音候选栏
 * - 符号键盘
 * - 九宫格数字键盘（GB/T 31921-2015 标准）
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PreviewScreen() {
    val engine = remember { PreviewEngine() }
    val outputText by remember { engine.outputText }
    val composing by remember { engine.composing }
    val candidates by remember { engine.candidates }

    KyrgyzKeyboardTheme {
        Scaffold(
            topBar = {
                TopAppBar(title = { Text("柯尔克孜语输入法预览") })
            }
        ) { padding ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding)
            ) {
                // 输出文本区（模拟编辑器）
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .padding(16.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(MaterialTheme.colorScheme.surfaceVariant)
                        .padding(16.dp)
                ) {
                    val displayText = outputText + composing
                    if (displayText.isEmpty()) {
                        Text(
                            text = "在此测试键盘输入...",
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                            fontSize = 16.sp
                        )
                    } else {
                        Text(
                            text = displayText,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            fontSize = 18.sp
                        )
                    }
                }

                // 拼音候选栏（仅拼音模式显示）
                if (engine.currentLanguage == Language.PINYIN && candidates.isNotEmpty()) {
                    CandidateBarPreview(
                        composing = composing,
                        candidates = candidates,
                        onPick = { engine.selectCandidate(it) }
                    )
                }

                // 键盘区域
                KeyboardPreview(engine = engine)
            }
        }
    }
}

/**
 * 预览用的键盘引擎包装类。
 * 模拟真实 InputMethodService 的行为，但输出到文本框而非系统编辑器。
 */
class PreviewEngine : KyrgyzKeyboardEngine.Listener {
    private val _outputText = mutableStateOf("")
    val outputText: androidx.compose.runtime.State<String> = _outputText

    private val _composing = mutableStateOf("")
    val composing: androidx.compose.runtime.State<String> = _composing

    private val _candidates = mutableStateOf<List<String>>(emptyList())
    val candidates: androidx.compose.runtime.State<List<String>> = _candidates

    // 用于在 shift / 语言 / 布局等非文本状态变化后触发重组
    private val _tick = mutableStateOf(0)
    val tick: Int get() = _tick.value

    val engine = KyrgyzKeyboardEngine(this)

    val currentLanguage: Language get() = engine.currentLanguage
    val currentLayout: LayoutType get() = engine.currentLayout
    val kyrgyzShift: Boolean get() = engine.kyrgyzShift
    val englishShift: Boolean get() = engine.englishShift
    val shiftLocked: Boolean get() = engine.shiftLocked

    override fun onKeyPress(code: String) {
        _outputText.value = _outputText.value + code
    }

    override fun onKeyAction(action: FunctionType) {
        when (action) {
            FunctionType.BACKSPACE -> {
                if (_composing.value.isNotEmpty()) {
                    // 拼音正在编辑时，先删拼音
                    _composing.value = _composing.value.dropLast(1)
                } else if (_outputText.value.isNotEmpty()) {
                    _outputText.value = _outputText.value.dropLast(1)
                }
            }
            FunctionType.SPACE -> _outputText.value = _outputText.value + " "
            FunctionType.NEWLINE -> _outputText.value = _outputText.value + "\n"
            else -> {}
        }
    }

    override fun onComposingChanged(composing: String) {
        _composing.value = composing
    }

    override fun onCommitCandidate(text: String) {
        _outputText.value = _outputText.value + text
        _composing.value = ""
        _candidates.value = emptyList()
    }

    fun selectCandidate(index: Int) {
        engine.selectCandidate(index)
        syncState()
    }

    /** 通知 Compose 重新读取引擎状态（shift / 语言 / 布局切换后调用）。 */
    fun syncState() {
        _tick.value = _tick.value + 1
    }
}

@Composable
private fun CandidateBarPreview(
    composing: String,
    candidates: List<String>,
    onPick: (Int) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(44.dp)
            .clip(RoundedCornerShape(6.dp))
            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f))
    ) {
        val scroll = rememberScrollState()
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .horizontalScroll(scroll)
                .padding(horizontal = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (composing.isNotEmpty()) {
                Text(
                    text = composing,
                    color = MaterialTheme.colorScheme.primary,
                    fontSize = 14.sp,
                    modifier = Modifier.padding(end = 12.dp)
                )
            }
            candidates.forEachIndexed { i, cand ->
                Box(
                    modifier = Modifier
                        .padding(horizontal = 4.dp)
                        .clip(RoundedCornerShape(4.dp))
                        .clickable { onPick(i) }
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = cand,
                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                        fontSize = 20.sp
                    )
                }
            }
        }
    }
}


@Composable
private fun KeyboardPreview(engine: PreviewEngine) {
    val rows = remember(engine.tick, engine.currentLanguage, engine.currentLayout, engine.kyrgyzShift, engine.englishShift) {
        engine.engine.getRows()
    }
    val isRtl = engine.currentLanguage == Language.KYRGYZ
    val direction = if (isRtl) LayoutDirection.Rtl else LayoutDirection.Ltr

    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Surface(
            color = MaterialTheme.colorScheme.surface,
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(4.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                val onKey: (KyrgyzKey) -> Unit = remember(engine) {
                    { k ->
                        engine.engine.handleKey(k)
                        engine.syncState()
                    }
                }
                val onVariant: (String) -> Unit = remember(engine) {
                    { v ->
                        engine.engine.handleVariant(v)
                        engine.syncState()
                    }
                }
                val shiftActive = if (engine.currentLanguage == Language.KYRGYZ) {
                    engine.kyrgyzShift
                } else {
                    engine.englishShift
                }
                rows.forEachIndexed { rowIndex, row ->
                    key(engine.currentLanguage, engine.currentLayout, engine.kyrgyzShift, engine.englishShift, rowIndex) {
                        KeyboardRowView(
                            row = row,
                            fontSize = 20f,
                            shiftActive = shiftActive,
                            shiftLocked = engine.shiftLocked,
                            onKey = onKey,
                            onVariant = onVariant,
                            onFeedback = {}
                        )
                    }
                }
            }
        }
    }
}
